fn add(a: i32, b: i32) -> i32 {
    a + b
}

fn divide(a: i32, b: i32) -> i32 {
    if b == 0 {
        panic!("divide by zero");
    }
    a / b
}

fn main() {
    println!("{} {}", add(2, 3), divide(10, 2));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn add_works() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn add_opposites() {
        assert_eq!(add(-2, 2), 0, "adding opposites should give zero");
    }

    #[test]
    fn divide_works() {
        assert!(divide(10, 2) == 5);
    }

    #[test]
    #[should_panic(expected = "divide by zero")]
    fn divide_by_zero_panics() {
        divide(1, 0);
    }
}

// Output when run normally (the tests are left out):
// 5 5

