fn is_even(n: i32) -> bool {
    n % 2 == 1
}

fn main() {
    assert_eq!(is_even(4), true);
    assert_eq!(is_even(10), true);
    // add assert!(!is_even(7)); here
    println!("all tests passed");
}

exercise.solution:
fn is_even(n: i32) -> bool {
    n % 2 == 0
}

fn main() {
    assert_eq!(is_even(4), true);
    assert_eq!(is_even(10), true);
    assert!(!is_even(7));
    println!("all tests passed");
}
